import {esc,toast} from './components.js';
import {steps,defaults,clone} from './workflow-store.js';
export function settingsMarkup(){return '<dialog id="workflow-settings" class="dialog wide-dialog" aria-labelledby="settings-title"></dialog>'}
export function bindSettings(s,persist,onChange){
 const modal=document.querySelector('#workflow-settings');let kind='prompts',step='script',scope='project',draft=null;
 function init(k){kind=k;draft={models:clone(s.models),prompts:clone(s.prompts),defaults:clone(s.defaults),styles:clone(s.styles),styleIndex:s.styleIndex};}
 function hold(){if(!draft)return;if(kind==='system'){draft.models[step]={provider:modal.querySelector('#provider').value,url:modal.querySelector('#model-url').value,name:modal.querySelector('#model-name').value,capability:modal.querySelector('#model-capability').value,credentialRef:modal.querySelector('#credential-ref').value,timeout:modal.querySelector('#model-timeout').value};}else if(kind==='prompts'){const target=scope==='project'?draft.prompts:draft.defaults;const before=scope==='project'?(draft.prompts[step]??draft.defaults[step]):draft.defaults[step];const value=modal.querySelector('#config-prompt').value;if(value!==before)target[step]=value;}else{draft.styles[draft.styleIndex]={name:modal.querySelector('#style-name').value,text:modal.querySelector('#style-text').value};}}
 function draw(){const m=draft.models[step]||{provider:'自定义服务',url:'',name:'',capability:['image'].includes(step)?'image':step==='video'?'video':['voice','music'].includes(step)?'audio':'text',credentialRef:'',timeout:120};
 modal.innerHTML=`<div class="panel-header"><div><p class="eyebrow">创作配置 · ${kind==='styles'?'视觉风格':steps[step]}</p><h2 id="settings-title">${{system:'系统配置',prompts:'提示词配置中心',styles:'风格模板配置'}[kind]}</h2></div><button class="button" id="settings-close">关闭</button></div><p class="config-help">本地交互演示；不连接服务、不填写真实密钥。保存后刷新可恢复，仅影响后续演示任务，已提交结果保留配置快照。</p><div class="settings-grid"><nav class="settings-menu" aria-label="配置环节">${kind==='styles'?draft.styles.map((v,i)=>`<button class="button ${i===draft.styleIndex?'primary':''}" data-style-tab="${i}">${esc(v.name)}</button>`).join('')+'<button class="button" id="add-style">＋ 新建风格模板</button>':Object.entries(steps).map(([id,name])=>`<button class="button ${id===step?'primary':''}" data-step="${id}">${name}</button>`).join('')}</nav><section>${kind==='system'?`<div class="field-pair"><label class="field">服务商<input type="text" id="provider" value="${esc(m.provider)}"></label><label class="field">模型标识<input type="text" id="model-name" placeholder="填写实际模型标识" value="${esc(m.name)}"></label></div><label class="field">服务地址<input type="url" id="model-url" placeholder="https://your-provider.example/api" value="${esc(m.url)}"></label><div class="field-pair"><label class="field">能力类型<select id="model-capability">${['text','image','video','audio'].map(x=>`<option ${x===m.capability?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">超时秒数<input type="number" id="model-timeout" min="1" value="${esc(m.timeout)}"></label></div><label class="field">凭据引用名称<input type="text" id="credential-ref" value="${esc(m.credentialRef)}" placeholder="例如：vault/my-provider；不要填写密钥"></label><p class="helper">真实实现由服务端管理密钥，本原型只保存引用名称。</p><button class="button" id="check-model">检查配置格式</button>`:kind==='prompts'?`<label class="field">生效范围<select id="prompt-scope"><option value="project" ${scope==='project'?'selected':''}>当前作品覆盖</option><option value="default" ${scope==='default'?'selected':''}>系统默认模板</option></select></label><p class="helper">当前来源：${s.prompts[step]?'作品自定义':'继承系统默认'}。系统默认更新不覆盖已存在的作品自定义。</p><label class="field">${steps[step]}提示词<textarea id="config-prompt">${esc(scope==='project'?(draft.prompts[step]??draft.defaults[step]):draft.defaults[step])}</textarea></label><p class="helper">必须保留变量：${esc((defaults[step].match(/\{\{\w+\}\}/g)||[]).join('、'))}</p><div class="row"><button class="button" id="preview-prompt">预览实际输入</button><button class="button" id="inherit-prompt">${scope==='project'?'恢复继承默认':'恢复初始模板'}</button></div><pre id="prompt-preview" class="notice" hidden></pre>`:`<label class="field">模板名称<input type="text" id="style-name" value="${esc(draft.styles[draft.styleIndex].name)}"></label><label class="field">风格描述 / 提示词<textarea id="style-text">${esc(draft.styles[draft.styleIndex].text)}</textarea></label><div class="row"><button class="button" id="assist-style">AI 完善模板（演示）</button><button class="button" id="style-prompt">模板提示词</button></div><p class="helper">保存并选用后影响新生成的参考图和视频；已有素材保留，并标记需要检查。</p>`}</section></div><p id="settings-error" class="error-text" role="alert"></p><div class="dialog-footer"><button class="button primary" id="settings-save">${kind==='styles'?'保存并选用模板':'保存配置'}</button></div>`;
 modal.querySelector('#settings-close').onclick=()=>{hold();modal.close();toast('面板草稿保留；使用保存配置后才生效')};modal.oncancel=()=>hold();
 modal.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{hold();step=b.dataset.step;draw()});modal.querySelectorAll('[data-style-tab]').forEach(b=>b.onclick=()=>{hold();draft.styleIndex=+b.dataset.styleTab;draw()});
 const error=t=>modal.querySelector('#settings-error').textContent=t;
 if(kind==='system')modal.querySelector('#check-model').onclick=()=>{hold();const v=draft.models[step];const expected=step==='image'?'image':step==='video'?'video':['voice','music'].includes(step)?'audio':'text';try{const url=new URL(v.url);if(!['https:','http:'].includes(url.protocol)||!v.name.trim()||v.capability!==expected||+v.timeout<=0)throw Error();error('格式检查通过；尚未进行网络连接测试。')}catch{error(`请填写有效 HTTP(S) 地址、模型标识和正数超时；本环节需要 ${expected} 能力。`)}};
 if(kind==='prompts'){modal.querySelector('#prompt-scope').onchange=e=>{const next=e.target.value;hold();scope=next;draw()};modal.querySelector('#inherit-prompt').onclick=()=>{if(scope==='project')delete draft.prompts[step];else draft.defaults[step]=defaults[step];draw()};modal.querySelector('#preview-prompt').onclick=()=>{hold();const values={idea:s.idea,instruction:s.instruction||'无追加要求',script:s.final?.text||'尚未选定剧本',shots:JSON.stringify(s.shots.map(({id,dialogue,prompt})=>({id,dialogue,prompt}))),shot:JSON.stringify(s.shots[0]||{}),style:s.styles[s.styleIndex].text,asset:s.shots[0]?.assets[0]?.description||'尚无素材描述',assets:JSON.stringify(s.shots[0]?.assets.map(a=>a.name)||[]),dialogue:s.shots[0]?.dialogue||'尚无台词',voice:s.finishing.voice,duration:'60秒'};const el=modal.querySelector('#prompt-preview');el.hidden=false;el.textContent=(scope==='project'?(draft.prompts[step]??draft.defaults[step]):draft.defaults[step]).replace(/\{\{(\w+)\}\}/g,(_,v)=>values[v]??`[缺失 ${v}]`)};}
 if(kind==='styles'){modal.querySelector('#add-style').onclick=()=>{hold();draft.styles.push({name:`自定义风格 ${draft.styles.length+1}`,text:''});draft.styleIndex=draft.styles.length-1;draw()};modal.querySelector('#assist-style').onclick=()=>{const el=modal.querySelector('#style-text');el.value+=(el.value?'\n':'')+'演示建议：统一角色服饰与色温；主体清晰，镜头运动平稳，保持同一视觉风格。';toast('已补入可编辑的模板示例，尚未保存')};modal.querySelector('#style-prompt').onclick=()=>{if(modal.querySelector('#style-template-prompt'))return;modal.querySelector('#style-prompt').insertAdjacentHTML('afterend',`<label class="field" style="width:100%">模板建立提示词<textarea id="style-template-prompt">${esc(s.prompts.template??s.defaults.template)}</textarea></label><p class="helper">保留 {{style}}；随保存并选用模板一起保存为当前作品覆盖。</p>`)};}
 modal.querySelector('#settings-save').onclick=()=>{hold();if(kind==='prompts'){const text=scope==='project'?(draft.prompts[step]??draft.defaults[step]):draft.defaults[step];const required=defaults[step].match(/\{\{\w+\}\}/g)||[];if(required.some(v=>!text.includes(v))){error('提示词缺少必填变量，请按下方变量说明补全。');return;}for(const [id,template]of Object.entries({...draft.defaults,...draft.prompts})){if((defaults[id].match(/\{\{\w+\}\}/g)||[]).some(v=>!template.includes(v))){error(`请修复 ${steps[id]} 的必填变量后再保存`);return;}}s.prompts=draft.prompts;s.defaults=draft.defaults;s.configVersion++;}else if(kind==='system'){const v=draft.models[step];const expected=step==='image'?'image':step==='video'?'video':['voice','music'].includes(step)?'audio':'text';if(!v.name.trim()||!/^https?:\/\/[^\s]+$/.test(v.url)||v.capability!==expected||!(+v.timeout>0)){error('配置未通过：请检查地址、模型标识、能力类型和超时。');return;}s.models=draft.models;s.configVersion++;}else{if(!draft.styles[draft.styleIndex].name.trim()||!draft.styles[draft.styleIndex].text.trim()){error('请补全模板名称与描述');return;}const templatePrompt=modal.querySelector('#style-template-prompt')?.value;if(templatePrompt!==undefined&&!templatePrompt.includes('{{style}}')){error('模板提示词必须保留 {{style}}');return;}if(templatePrompt!==undefined){s.prompts.template=templatePrompt;s.configVersion++;}const styleChanged=JSON.stringify(s.styles[s.styleIndex])!==JSON.stringify(draft.styles[draft.styleIndex]);s.styles=draft.styles;s.styleIndex=draft.styleIndex;if(styleChanged){s.styleVersion++;s.shots.forEach(sh=>{sh.assets.forEach(a=>a.confirmed=false);sh.videoStale=!!sh.video});}}if(!persist())return;modal.close();onChange();toast('配置已保存；新任务使用新版本，旧结果保留');};
 }
 return function open(k,selectedStep='script'){if(kind!==k||!draft)init(k);step=selectedStep;draw();modal.showModal();};
}
